import codecs, sys, unicodedata, platform, json
print(json.dumps(dict(version=sys.version, unicode=unicodedata.unidata_version, platform=platform.platform(), byteorder=sys.byteorder)))
try:
    codecs.IncrementalEncoder().encode('')
except NotImplementedError as error:
    tb = error.__traceback__
    while tb is not None:
        print(tb.tb_frame.f_code.co_name, tb.tb_lineno, tb.tb_lasti)
        tb = tb.tb_next

